function PresenterOverlay({doc,fileId,mode,index,setIndex,close,elapsed,timerStartedAt,setTimerStartedAt,timerPaused,setTimerPaused,setElapsed,blackout,setBlackout}:{doc:ShowDocument;fileId:string;mode:ShowPresenterMode;index:number;setIndex:(n:number)=>void;close:()=>void;elapsed:number;timerStartedAt:number|null;setTimerStartedAt:(n:number|null)=>void;timerPaused:boolean;setTimerPaused:(v:boolean|((prev:boolean)=>boolean))=>void;setElapsed:(n:number)=>void;blackout?:false|true|'white';setBlackout?:(v:any)=>void}){
  const current=presenterCurrent(doc,index); const next=presenterNext(doc,index);
  const go=(n:number)=>setIndex(clampSlideIndex(doc,n));
  if(mode==='audience') return <div className="fixed inset-0 z-50 flex items-center justify-center bg-black" onClick={close}><div className="relative h-[94vh] w-[min(98vw,1600px)] overflow-hidden bg-white shadow-2xl" onClick={e=>e.stopPropagation()} style={{aspectRatio:doc.aspectRatio==='16:9'?16/9:4/3,background:current.backgroundImage?undefined:current.background,backgroundImage:current.backgroundImage?`url(${current.backgroundImage})`:undefined,backgroundSize:'cover'}}>{current.elements.map(e=><ElementView key={e.id} e={e} selected={false} onSelect={()=>{}} onChange={()=>{}} onDragStart={()=>{}}/>)}{blackout?<div className="absolute inset-0 z-20" style={{background:blackout==='white'?'#fff':'#000'}}/>:null}<div className="absolute bottom-3 left-1/2 -translate-x-1/2 rounded bg-black/60 px-3 py-1 text-xs text-white">← → Navigate · B Blackout · W White · Esc Exit · Slide {index+1}/{doc.slides.length}</div></div></div>;
  return <div className="fixed inset-0 z-50 grid grid-cols-[1fr_360px] bg-slate-950 text-white"><section className="flex min-w-0 flex-col"><div className="flex h-12 items-center justify-between border-b border-white/10 px-4 text-sm"><span>Presenter View · {doc.title}</span><div className="flex items-center gap-2"><span className="font-mono">{formatPresenterTime(elapsed)}</span><button className="rounded border border-white/20 px-2 py-1 text-xs" onClick={()=>{if(timerStartedAt===null)setTimerStartedAt(Date.now());else{setTimerStartedAt(null);setTimerPaused(false);setElapsed(0)}}}> {timerStartedAt===null?'Start timer':'Reset timer'}</button><button className="rounded border border-white/20 px-2 py-1 text-xs" onClick={close}>Exit</button></div></div><div className="flex flex-1 items-center justify-center p-6"><div className="relative w-full max-w-[1100px] overflow-hidden bg-white shadow-2xl" style={{aspectRatio:doc.aspectRatio==='16:9'?16/9:4/3,background:current.backgroundImage?undefined:current.background,backgroundImage:current.backgroundImage?`url(${current.backgroundImage})`:undefined,backgroundSize:'cover'}}>{current.elements.map(e=><ElementView key={e.id} e={e} selected={false} onSelect={()=>{}} onChange={()=>{}} onDragStart={()=>{}}/>)}{blackout?<div className="absolute inset-0 z-20" style={{background:blackout==='white'?'#fff':'#000'}}/>:null}<div className="absolute bottom-3 left-1/2 -translate-x-1/2 rounded bg-black/60 px-3 py-1 text-xs">Slide {index+1}/{doc.slides.length} · B blackout</div></div></div><div className="flex items-center justify-center gap-2 border-t border-white/10 p-3"><button className="rounded border border-white/20 px-3 py-1" onClick={()=>go(index-1)}>← Previous</button><button className="rounded border border-white/20 px-3 py-1" onClick={()=>go(index+1)} disabled={!next}>Next →</button><button className="rounded border border-white/20 px-3 py-1" onClick={()=>window.open(presenterUrl(fileId,'audience',index),'_blank','noopener,noreferrer')}>Open Presentation Window</button></div></section><aside className="overflow-auto border-l border-white/10 bg-slate-900 p-3"><div className="mb-2 text-xs font-semibold">Current Slide · Speaker Notes</div><div className="mb-4 rounded border border-white/10 bg-white/5 p-2 text-xs">{current.notes||'No speaker notes for this slide.'}</div><div className="mb-2 text-xs font-semibold">Next Slide</div>{next?<div className="mb-4"><div className="relative mb-2 aspect-video overflow-hidden rounded border border-white/10 bg-white" style={{background:next.backgroundImage?undefined:next.background,backgroundImage:next.backgroundImage?`url(${next.backgroundImage})`:undefined,backgroundSize:'cover'}}>{next.elements.slice(0,12).map(e=><div key={e.id} className="absolute overflow-hidden text-[6px] leading-tight text-black" style={{left:`${e.x}%`,top:`${e.y}%`,width:`${e.width}%`,height:`${e.height}%`,background:e.type==='shape'?e.fill:undefined}}>{e.type==='text'?(e.text||'').slice(0,40):''}</div>)}</div><div className="rounded border border-white/10 bg-white/5 p-2 text-xs">Slide {index+2}: {next.notes||'No notes'}</div></div>:<div className="mb-4 text-xs text-slate-400">End of presentation</div>}<div className="mb-2 flex items-center justify-between text-xs font-semibold"><span>Slide Navigator</span><button className="rounded border border-white/20 px-2 py-1" onClick={()=>setTimerPaused(v=>!v)}>{timerPaused?'Resume timer':'Pause timer'}</button></div><div className="grid grid-cols-4 gap-2">{doc.slides.map((s,i)=><button key={s.id} onClick={()=>go(i)} className={`aspect-video overflow-hidden rounded border text-[10px] ${i===index?'border-blue-400 ring-1 ring-blue-400':'border-white/10 bg-white/5'}`}>{i+1}</button>)}</div></aside></div>;
}

function Inspector({e,onChange}:{e:ShowElement;onChange:(p:Partial<ShowElement>)=>void}){if(!e)return null;const animations=e.animations?.length?e.animations:(e.animation?[e.animation]:[]);return <div className="mt-4 space-y-2 border-t pt-3 text-xs"><div className="font-semibold">Object</div>{e.type==='text'&&<textarea className="w-full rounded border p-2" rows={4} value={e.text||''} onChange={x=>onChange({text:x.target.value})}/>}<div className="grid grid-cols-2 gap-2">{(['x','y','width','height','rotation'] as const).map(k=><label key={k}>{k}<input className="mt-1 w-full rounded border p-1" type="number" value={e[k]||0} onChange={x=>onChange({[k]:Number(x.target.value)} as any)}/></label>)}</div>{(e.type==='image'||e.type==='video'||e.type==='audio')&&<label>Media URL<input className="mt-1 w-full rounded border p-1" value={e.src||''} onChange={x=>onChange({src:x.target.value})}/></label>}{e.type==='video'&&<label>Poster image<input className="mt-1 w-full rounded border p-1" value={e.poster||''} onChange={x=>onChange({poster:x.target.value})}/></label>}{(e.type==='video'||e.type==='audio')&&<div className="space-y-2 rounded border p-2"><div className="font-semibold">Media controls</div><div className="flex flex-wrap gap-2"><label><input type="checkbox" checked={!!e.mediaAutoplay} onChange={x=>onChange({mediaAutoplay:x.target.checked})}/> Autoplay</label><label><input type="checkbox" checked={!!e.mediaLoop} onChange={x=>onChange({mediaLoop:x.target.checked})}/> Loop</label><label><input type="checkbox" checked={!!e.mediaMuted} onChange={x=>onChange({mediaMuted:x.target.checked})}/> Mute</label></div><label className="block">Volume {Math.round((e.mediaVolume??1)*100)}%<input className="w-full" type="range" min="0" max="1" step="0.05" value={e.mediaVolume??1} onChange={x=>onChange({mediaVolume:Number(x.target.value)})}/></label><div className="grid grid-cols-2 gap-2"><label>Trim start<input className="mt-1 w-full rounded border p-1" type="number" min="0" step="0.1" value={e.mediaTrimStart||0} onChange={x=>onChange({mediaTrimStart:Math.max(0,Number(x.target.value)||0)})}/></label><label>Trim end<input className="mt-1 w-full rounded border p-1" type="number" min="0" step="0.1" value={e.mediaTrimEnd||0} onChange={x=>onChange({mediaTrimEnd:Math.max(0,Number(x.target.value)||0)})}/></label></div></div>}{e.type==='text'&&<><label>Font<input className="mt-1 w-full rounded border p-1" value={e.fontFamily||'Arial'} onChange={x=>onChange({fontFamily:x.target.value})}/></label><label>Size<input className="mt-1 w-full rounded border p-1" type="number" value={e.fontSize||20} onChange={x=>onChange({fontSize:Number(x.target.value)})}/></label></>}<div className="flex flex-wrap gap-2"><label><input type="checkbox" checked={!!e.bold} onChange={x=>onChange({bold:x.target.checked})}/> Bold</label><label><input type="checkbox" checked={!!e.italic} onChange={x=>onChange({italic:x.target.checked})}/> Italic</label><label><input type="checkbox" checked={!!e.underline} onChange={x=>onChange({underline:x.target.checked})}/> Underline</label></div><div className="rounded border p-2"><div className="mb-2 font-semibold">Animation timeline</div><div className="mb-2 grid grid-cols-3 gap-1"><button className="tool" onClick={()=>onChange({animations:[...animations,{type:'fade',phase:'entrance',duration:500,delay:0,order:animations.length+1,trigger:'on-click'}]})}>Entrance</button><button className="tool" onClick={()=>onChange({animations:[...animations,{type:'pulse',phase:'emphasis',duration:500,delay:0,order:animations.length+1,trigger:'after-previous'}]})}>Emphasis</button><button className="tool" onClick={()=>onChange({animations:[...animations,{type:'fade',phase:'exit',duration:500,delay:0,order:animations.length+1,trigger:'after-previous'}]})}>Exit</button></div>{animations.map((a:any,i:number)=><div key={i} className="mb-2 rounded border bg-slate-50 p-2"><div className="flex items-center justify-between"><span>#{i+1} {a.phase}</span><button className="text-red-600" onClick={()=>onChange({animations:animations.filter((_:any,j:number)=>j!==i)})}>Remove</button></div><div className="grid grid-cols-2 gap-2"><label>Effect<select className="mt-1 w-full rounded border p-1" value={a.type} onChange={x=>onChange({animations:animations.map((v:any,j:number)=>j===i?{...v,type:x.target.value}:v)})}><option value="fade">Fade</option><option value="zoom">Zoom</option><option value="slide-in">Slide In</option><option value="float">Float</option><option value="pulse">Pulse</option><option value="spin">Spin</option></select></label><label>Phase<select className="mt-1 w-full rounded border p-1" value={a.phase||'entrance'} onChange={x=>onChange({animations:animations.map((v:any,j:number)=>j===i?{...v,phase:x.target.value}:v)})}><option value="entrance">Entrance</option><option value="emphasis">Emphasis</option><option value="exit">Exit</option></select></label><label>Duration<input className="mt-1 w-full rounded border p-1" type="number" value={a.duration} onChange={x=>onChange({animations:animations.map((v:any,j:number)=>j===i?{...v,duration:Number(x.target.value)}:v)})}/></label><label>Delay<input className="mt-1 w-full rounded border p-1" type="number" value={a.delay} onChange={x=>onChange({animations:animations.map((v:any,j:number)=>j===i?{...v,delay:Number(x.target.value)}:v)})}/></label><label>Order<input className="mt-1 w-full rounded border p-1" type="number" min="1" value={a.order||i+1} onChange={x=>onChange({animations:animations.map((v:any,j:number)=>j===i?{...v,order:Number(x.target.value)}:v)})}/></label><label>Trigger<select className="mt-1 w-full rounded border p-1" value={a.trigger||'on-click'} onChange={x=>onChange({animations:animations.map((v:any,j:number)=>j===i?{...v,trigger:x.target.value}:v)})}><option value="on-click">On click</option><option value="with-previous">With previous</option><option value="after-previous">After previous</option></select></label></div></div>)}</div></div>}

